const CACHE='whg-static';
const IMG='whg-geo-v1';
// 联播听书那一格：切片名带内容哈希（构建期不可知），故不进 install 预缓存清单，
// 由页面侧预热（web/src/lib/player.ts 的 warmToday）往里放、往外扫。改名要两处一起改。
const AUD='whg-news-audio-v1';
// 欠账单：这一次没装齐的条目清单。它在，就说明兜里缺斤短两——
// 此时绝不清退旧资产（留着当后备），并等页面下次开起来喊一声 refill 把缺的补上。
const BILL='/whg/__pending__';
const SHELL=['/whg/','/whg/index.html'];
const KEEP=new Set(ASSETS);
const IKEEP=new Set(IMGS);
// 每条资产按路径认自己那一格：图归 whg-geo-v1，其余归 whg-static。
function isImg(u){return u.startsWith('/whg-geo')}
// 听书的地界：菜单与切片都在 /whg/audio/ 底下
function isAud(p){return p.startsWith('/whg/audio/')}
// 蜂窝网守门。navigator.connection 只有安卓 Chrome 系有；iOS/桌面取不到＝当 WiFi 办。
function isCell(){return !!(self.navigator.connection&&self.navigator.connection.type==='cellular')}
// 验货闸：按扩展名核对 Content-Type。代理或部署传播窗口里对着 .js 回一份 200 的 HTML 是常事，
// 那份错货一旦进兜就永远命中，白屏重试到天荒地老也好不了。不过闸的响应照常交给页面，只是绝不入缓存。
function typeOk(p,r){
  if(!r||!r.ok)return false;
  const t=(r.headers.get('Content-Type')||'').toLowerCase();
  let e=p.charAt(p.length-1)==='/'?'html':'';
  if(!e){const i=p.lastIndexOf('.');e=i<0?'':p.slice(i+1).toLowerCase();}
  if(e==='js')return t.indexOf('javascript')>=0;
  if(e==='css')return t.indexOf('css')>=0;
  if(e==='json')return t.indexOf('json')>=0;
  if(e==='html')return t.indexOf('html')>=0;
  if(e==='svg')return t.indexOf('svg')>=0;
  if(e==='png'||e==='jpg'||e==='jpeg'||e==='webp'||e==='gif')return t.indexOf('image')>=0;
  if(e==='woff'||e==='woff2')return t.indexOf('font')>=0||t.indexOf('woff')>=0;
  // 听书切片。GitHub Pages 实测回的是 audio/mp3（2026-07-29 curl 线上 tts-samples/yunyang.mp3
  // 实证），不是 audio/mpeg——只认 audio/mpeg 会把线上音频全判成错货、一条都进不了兜。
  // 故按 audio/* 放行，另收 octet-stream（有些代理对 mp3 就回这个）。
  if(e==='mp3')return t.indexOf('audio/')>=0||t.indexOf('octet-stream')>=0;
  return true;
}
// 取一条、验货、进自己那一格、原位覆盖。取不到或不过闸绝不留空洞——旧条目原样留着。
// 三种结局：OK＝进兜了；RETRY＝这次没成，记进欠账单下次再来；DROP＝装不下，认了，别再来。
const OK=1,RETRY=0,DROP=-1;
// 手机存满时 Cache.put 抛的东西：标准是 DOMException{name:'QuotaExceededError'}，
// 老实现只给 code 22（QUOTA_EXCEEDED_ERR），两种都认。
function isQuota(e){return !!e&&(e.name==='QuotaExceededError'||e.code===22)}
async function fill(cs,ci,u){
  let r;
  try{r=await fetch(u)}catch(_){return RETRY}
  try{
    if(!typeOk(new URL(u,self.location.href).pathname,r))return RETRY;
    await (isImg(u)?ci:cs).put(u,r);
    return OK;
  }catch(e){
    // 设备存满了：这一条无论重试多少次都装不进去。再记进欠账单，就成了每次开 App
    // 拿着流量把装不下的东西重下一遍——白烧流量还永远清不掉账。就此放弃这一条：
    // 家人在线照样看得见这张图，只是它不进离线兜。
    if(isQuota(e)){console.warn('配额满，放弃离线：'+u);return DROP}
    return RETRY;
  }
}
// 分批下载：清单上千条，一把 Promise.all 全发出去会把低端机的内存和连接池顶穿
// （旧机器上表现为装到一半整个 SW 被系统杀掉，然后每次开 App 重来一遍）。
// 每批 24 条并发、批间顺序 await：慢一点，但装得完。
const BATCH=24;
async function fillAll(cs,ci,list){
  const missing=[];
  for(let i=0;i<list.length;i+=BATCH){
    const part=list.slice(i,i+BATCH);
    await Promise.all(part.map(async(u)=>{if((await fill(cs,ci,u))===RETRY)missing.push(u)}));
  }
  return missing;
}
function billOf(list){return new Response(JSON.stringify(list),{headers:{'Content-Type':'application/json'}})}
// 清退清单外的旧条目：只在补装完整（无欠账）时才做。两格各查各的清单。
// 图那格连 ?query 一起比（qs=1）：图片内容改了、URL 没变时，我们靠给清单里的图升
// ?v=N 来击穿代理与本格缓存；若只按 pathname 认，刚装好的 ...1.jpg?v=2 会因"pathname
// 不在清单里"当场被自己清掉（每次发布重下一遍、且离线看不到），而该退休的旧条目反而留下。
// 页面资产那格照旧只按 pathname（取用侧是 ignoreSearch 匹配的，带参变体清掉才对）。
async function sweep(c,keep,qs){
  for(const req of await c.keys()){
    const u=new URL(req.url);
    const p=qs?u.pathname+u.search:u.pathname;
    if(u.pathname===BILL)continue;
    if(!keep.has(p))await c.delete(req);
  }
}
async function sweepAll(cs,ci){await sweep(cs,KEEP,0);await sweep(ci,IKEEP,1)}
self.addEventListener('install',(e)=>{e.waitUntil((async()=>{
  const c=await caches.open(CACHE);
  const ci=await caches.open(IMG);
  const cell=isCell();
  // 壳每次都重取（覆盖式更新，取不到就留旧的）；其余只补缺——
  // 「在兜但验货不过」（历史毒条目）也算缺，趁 install 一并重取，兜里永远是对的货
  const need=[];
  for(const u of ASSETS){
    if(SHELL.indexOf(u)>=0){need.push(u);continue}
    const had=await c.match(u,{ignoreVary:true});
    if(!had||!typeOk(new URL(u,self.location.href).pathname,had))need.push(u);
  }
  // WiFi 守门：蜂窝网下缺的图这一趟一张不取（几百兆，别在流量上偷跑），
  // 但要原样记进欠账单——等哪次开 App 时连着 WiFi，refill 自然把它们补齐。
  const defer=[];
  for(const u of IMGS){
    const had=await ci.match(u,{ignoreVary:true});
    if(had&&typeOk(new URL(u,self.location.href).pathname,had))continue;
    if(cell)defer.push(u);else need.push(u);
  }
  const missing=defer.concat(await fillAll(c,ci,need));
  if(missing.length)await c.put(BILL,billOf(missing));else await c.delete(BILL);
  self.skipWaiting();
})())});
self.addEventListener('activate',(e)=>{e.waitUntil((async()=>{
  const c=await caches.open(CACHE);
  if(!(await c.match(BILL)))await sweepAll(c,await caches.open(IMG));
  await self.clients.claim();
})())});
// 补漏自愈：页面每次成功启动都发一声 {t:'refill'}，把欠账逐条补上、销账；
// 账清了才删欠账单并清退一次。任何残局都在下一次正常打开时收敛，家人零操作。
self.addEventListener('message',(e)=>{
  if(!e.data||e.data.t!=='refill')return;
  const job=(async()=>{
    const c=await caches.open(CACHE);
    const ci=await caches.open(IMG);
    const b=await c.match(BILL);
    if(!b)return;
    let list=null;
    try{list=await b.json()}catch(_){}
    if(!Array.isArray(list))list=[];
    // 补漏这条路也守蜂窝网：图片欠账原样留在账上等 WiFi，只补页面资产。
    // （不守的话，装了一半的那几百张图会在每次开 App 时拿着流量重下。）
    const cell=isCell();
    const defer=cell?list.filter(isImg):[];
    const todo=cell?list.filter((u)=>!isImg(u)):list;
    const left=defer.concat(await fillAll(c,ci,todo));
    if(left.length)await c.put(BILL,billOf(left));
    else{await c.delete(BILL);await sweepAll(c,ci)}
  })();
  if(e.waitUntil)e.waitUntil(job);
});
self.addEventListener('fetch',(e)=>{
  const req=e.request;
  if(req.method!=='GET')return;
  const url=new URL(req.url);
  if(url.origin!==location.origin)return;
  // 拦截范围＝主站 /whg/ ＋图床三仓 /whg-geo1|2|3/。后者没有 /whg/ 前缀（注意斜杠），
  // 只查 startsWith('/whg/') 会把图整批漏在拦截之外，离线时图全裂。
  const inScope=url.pathname.startsWith('/whg/')||url.pathname.startsWith('/whg-geo');
  if(!inScope)return;
  // 风景文章图在同域的兄弟图床 /whg-geo1|2|3/：自成一格 whg-geo-v1。
  // install 已按清单把它们整批预装进这一格，这里直接命中即离线可用；
  // 清单外（临时点开的）也见一张存一张。与应用壳那格分开＝管理台手术刀删 whg-static
  // 治白屏时，几百兆的图一张不少。ignoreVary 同全站：预装是按 URL 字符串 put 的，
  // 页面来的是 Request，将来 CDN 一发 Vary 就会静默失配，整兜图白装。
  if(/^\/whg-geo\d+\//.test(url.pathname)){
    e.respondWith((async()=>{
      const c=await caches.open(IMG);
      const hit=await c.match(req,{ignoreVary:true});
      if(hit)return hit;
      try{
        const r=await fetch(req);
        // 存不下（手机配额到顶）就当没存过，照样把图给页面，绝不因此报错
        if(r.ok)try{await c.put(req,r.clone())}catch(_){}
        return r;
      }catch(_){return Response.error()}
    })());
    return;
  }
  if(url.pathname==='/whg/sw.js'||url.pathname==='/whg/notify.json'||url.pathname==='/whg/notify2.json'||url.pathname==='/whg/shell.json')return; // 探测类文件直连网络，永不缓存
  // 联播听书：自成一格 whg-news-audio-v1，与页面资产、风景图三格互不干扰。
  //   · manifest.json 网络优先（限时 3 秒）：切片文件名带内容哈希，只有菜单换了才知道
  //     今晚有新音频；被墙/慢网时立刻回退本地那份，照样能听昨晚存下的。
  //   · .mp3 缓存优先：预热过的当天音频本地秒开，miss 才下网并顺手入格。
  //     存不下（配额到顶）就当没存过，照样把音频给页面——绝不因此让家人听不成。
  if(isAud(url.pathname)){
    e.respondWith((async()=>{
      const c=await caches.open(AUD);
      if(url.pathname.slice(-13)==='manifest.json'){
        try{
          const ac=new AbortController();
          const to=setTimeout(()=>ac.abort(),3000);
          let r;
          try{r=await fetch(req,{signal:ac.signal})}finally{clearTimeout(to)}
          if(!r)throw new Error('man empty');
          // 404＝那天真没配音：照实回给页面，前端据此一枚听书钮都不摆
          if(r.status===404)return r;
          if(!r.ok||!typeOk(url.pathname,r))throw new Error('man '+r.status);
          try{await c.put(req,r.clone())}catch(_){}
          return r;
        }catch(_){
          const hit=await c.match(req,{ignoreVary:true});
          if(hit)return hit;
          try{return await fetch(req)}catch(_e){return Response.error()}
        }
      }
      const hit=await c.match(req,{ignoreVary:true});
      if(hit)return hit;
      try{
        const r=await fetch(req);
        if(r.ok&&typeOk(url.pathname,r)){try{await c.put(req,r.clone())}catch(err){if(isQuota(err))console.warn('配额满，音频不入格：'+url.pathname)}}
        return r;
      }catch(_){return Response.error()}
    })());
    return;
  }
  if(req.mode==='navigate'){
    // 开页面一律先问网络（发布后第一次打开就是新版），但只等 3 秒——
    // 被墙/慢网把请求吊死时立刻回退本地那份，绝不白屏干等。
    e.respondWith((async()=>{
      const c=await caches.open(CACHE);
      try{
        const ac=new AbortController();
        const to=setTimeout(()=>ac.abort(),3000);
        let r;
        try{r=await fetch(req,{signal:ac.signal})}finally{clearTimeout(to)}
        if(!r||!r.ok)throw new Error('nav '+(r&&r.status));
        if(typeOk('/whg/',r))c.put('/whg/',r.clone());
        return r;
      }catch(_){
        const hit=(await c.match('/whg/',{ignoreVary:true}))||(await c.match('/whg/index.html',{ignoreVary:true}));
        if(hit)return hit;
        try{return await fetch(req)}catch(_e){return Response.error()}
      }
    })());
    return;
  }
  e.respondWith((async()=>{
    // ignoreVary：静态资产无内容协商，而 CDN 的 Vary 头（如 Vary:Origin）会让
    // 「存时带某请求头、取时不带」的条目静默失配——离线兜整个变摆设。一律忽略。
    const hit=await caches.match(req,{ignoreSearch:true,ignoreVary:true});
    // 命中也过验货闸：历史上混进兜的错货（HTML 冒充 JS 之类）当场销毁、改走网络——
    // 白屏就防在这道验货闸上；类型对但内容坏的极端货色已无自动兜底（看门狗已拆）——
    // 表现＝一直打不开，救济路径＝主人向日葵进管理台按手术修复
    if(hit){
      if(typeOk(url.pathname,hit))return hit;
      try{const c=await caches.open(CACHE);await c.delete(req,{ignoreSearch:true})}catch(_){}
    }
    try{
      const r=await fetch(req);
      // 验货不过就只给页面看，绝不入兜（毒条目进了兜就是永久白屏）
      if(typeOk(url.pathname,r)){const c=await caches.open(CACHE);c.put(req,r.clone());}
      return r;
    }catch(_){
      return Response.error();
    }
  })());
});
